item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input      cpu_overheated,
    output reg shut_off_computer,
    input      arrived,
    input      gas_tank_empty,
    output reg keep_driving
);
    always_comb begin
        if (cpu_overheated)
            shut_off_computer = 1'b1;
        else
            shut_off_computer = 1'b0;
    end

    always_comb begin
        if (~arrived)
            keep_driving = ~gas_tank_empty;
        else
            keep_driving = 1'b0;
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
module dev_tb;
    reg cpu_overheated, arrived, gas_tank_empty;
    wire shut_off_computer, keep_driving;
    integer i, j;
    TopModule dut (.*);
    initial begin
        for (j = 0; j < 2; j = j + 1) begin
            for (i = 0; i < 8; i = i + 1) begin
                {cpu_overheated, arrived, gas_tank_empty} = j ? (7-i) : i;
                #1;
                if (shut_off_computer "'!== cpu_overheated ||
                    keep_driving !== (!arrived && !gas_tank_empty))
                    $fatal(1, "FAIL input=%b%b%b output=%b%b", cpu_overheated,
                           arrived, gas_tank_empty, shut_off_computer, keep_driving);
            end
        end
        $display("PASS: all binary inputs checked in forward and reverse order");
        $finish;
    end
    initial begin
        #100;
        $fatal(1, "FAIL: timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
compile_status=$?
printf '"'%s\\n' \""'$compile_status" > compile.exit
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > simulation.log 2>&1
    printf '"'%s\\n' \""'$?" > simulation.exit
fi
cat compile.log compile.exit simulation.log simulation.exit'

